mapper.select:
select n.id, n.nursing_id, n.project_id, n.project_name, n.elder_id,
       n.elder_name, n.bed_number, n.estimated_server_time,
       n.real_server_time, n.mark, n.cancel_reason, n.status,
       n.task_image, n.create_by, n.create_time, n.update_by,
       n.update_time, n.remark
from nursing_task n


        and n.elder_name like concat('%', #{elderName}, '%')

    and n.project_id = #{projectId}
    and n.estimated_server_time >= #{startTime}
    and n.estimated_server_time <= #{endTime}
    and n.status = #{status}

        and (
            exists (
                select 1 from nursing_task_assignee nta
                where nta.task_id = n.id and nta.nursing_id = #{nurseId}
            )
            or find_in_set(#{nurseId}, n.nursing_id) > 0
        )


order by n.estimated_server_time, n.id

select count(1)
from nursing_task
where elder_id = #{elderId}
  and project_id = #{projectId}
  and estimated_server_time = #{estimatedServerTime}
  and status in (1, 2)
